#import <Foundation/Foundation.h>
#include "qn_qwen4_layer.h"
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
static void*rd(const char*p,size_t n){FILE*f=fopen(p,"rb");if(!f){perror(p);exit(1);}void*x=malloc(n);if(fread(x,1,n,f)!=n){fprintf(stderr,"short %s\n",p);exit(2);}fclose(f);return x;}
static void st(const float*a,const float*b,size_t N,double*mx,double*ma,double*rm,double*cos){double m=0,s=0,e2=0,d=0,aa=0,bb=0;for(size_t i=0;i<N;i++){double e=(double)a[i]-b[i],z=fabs(e);if(z>m)m=z;s+=z;e2+=e*e;d+=(double)a[i]*b[i];aa+=(double)a[i]*a[i];bb+=(double)b[i]*b[i];}*mx=m;*ma=s/N;*rm=sqrt(e2/N);*cos=d/sqrt(aa*bb);}
int main(int ac,char**av){if(ac!=5){fprintf(stderr,"usage: %s layer model_dir manifest oracle_dir\n",av[0]);return 2;}int L=atoi(av[1]);const char*model_dir=av[2],*manifest=av[3],*oracle=av[4];char dir[1024],p[1200];snprintf(dir,sizeof(dir),"%s",oracle);const uint32_t pos=2560;snprintf(p,sizeof(p),"%s/hyper.bin",dir);float*h=rd(p,10240*4);snprintf(p,sizeof(p),"%s/rawk.bin",dir);float*i=rd(p,(size_t)pos*128*4);snprintf(p,sizeof(p),"%s/K.bin",dir);float*k=rd(p,(size_t)pos*512*4);snprintf(p,sizeof(p),"%s/V.bin",dir);float*v=rd(p,(size_t)pos*512*4);snprintf(p,sizeof(p),"%s/final.bin",dir);float*ref=rd(p,10240*4);snprintf(p,sizeof(p),"%s/route_ids.bin",dir);int*rid=rd(p,10*4);float*outb=malloc(10240*4);@autoreleasepool{qn_qwen4_layer*l=0;char e[512]={0};qn_qwen4_layer_config c={0};c.layer_index=L;c.model_dir=model_dir;c.manifest_path=manifest;if(qn_qwen4_layer_open(&l,&c,e,sizeof(e))){fprintf(stderr,"L%d open %s\n",L,e);return 3;}qn_qwen4_decode_input in={h,i,k,v,pos};qn_qwen4_decode_output o={0};o.hyper_state=outb;if(qn_qwen4_layer_forward_decode(l,&in,&o,e,sizeof(e))){fprintf(stderr,"L%d fw %s\n",L,e);return 4;}int mis=0;for(int z=0;z<10;z++)if((int)o.selected_expert_ids[z]!=rid[z])mis++;double mx,ma,rm,cs;st(outb,ref,10240,&mx,&ma,&rm,&cs);printf("L%02d total=%.4fms route_mismatch=%d max=%.8g mae=%.8g rmse=%.8g cos=%.12f ids=",L,o.total_ms,mis,mx,ma,rm,cs);for(int z=0;z<10;z++)printf("%u%s",o.selected_expert_ids[z],z==9?"\n":" ");qn_qwen4_layer_close(l);}return 0;}
